@RestController @RequestMapping("/api")
public class ApiController {
 private final JdbcTemplate db;
 public ApiController(JdbcTemplate db){this.db=db;}
 @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","UP","app","TRANSITVOICE","database","JDBC connected");}
 @PostMapping("/auth/register") public ResponseEntity<?> register(@RequestBody Map<String,String> p){try{db.update("INSERT INTO passengers(name,email,phone,password) VALUES(?,?,?,?)",p.get("name"),p.get("email"),p.get("phone"),p.getOrDefault("password","demo123"));return ResponseEntity.ok(Map.of("message","Registration successful"));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Email may already be registered"));}}
 @PostMapping("/auth/login") public ResponseEntity<?> login(@RequestBody Map<String,String> p){var rows=db.queryForList("SELECT id,name,email,points FROM passengers WHERE email=? AND password=?",p.get("email"),p.get("password")); if(rows.isEmpty())return ResponseEntity.status(401).body(Map.of("error","Invalid email or password"));return ResponseEntity.ok(rows.get(0));}
 @GetMapping("/routes") public List<Map<String,Object>> routes(){return db.queryForList("SELECT * FROM routes ORDER BY demand DESC");}
 @GetMapping("/surveys/settings") public Map<String,Object> surveySettings(){return db.queryForMap("SELECT * FROM survey_settings WHERE id=1");}
 @PostMapping("/admin/surveys/toggle") public Map<String,Object> toggleSurvey(@RequestBody Map<String,Object> p){boolean open=Boolean.parseBoolean(Objects.toString(p.getOrDefault("isOpen",false)));String title=Objects.toString(p.getOrDefault("title","Weekly passenger travel survey"));String week=Objects.toString(p.getOrDefault("weekLabel","Weekly survey"));db.update("UPDATE survey_settings SET is_open=?,title=?,week_label=?,updated_at=CURRENT_TIMESTAMP WHERE id=1",open,title,week);return Map.of("isOpen",open,"title",title,"weekLabel",week);}
 @PostMapping("/surveys/demand") public Map<String,Object> submitDemandSurvey(@RequestBody Map<String,Object> p){Boolean open=db.queryForObject("SELECT is_open FROM survey_settings WHERE id=1",Boolean.class);if(!Boolean.TRUE.equals(open))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.CONFLICT,"Weekly survey is currently closed");db.update("INSERT INTO survey_responses(passenger_id,origin,destination,reason,preferred_time,passengers_count) VALUES(?,?,?,?,?,?)",lng(p,"passengerId"),p.get("origin"),p.get("destination"),p.get("reason"),p.get("preferredTime"),Math.max(1,integer(p,"passengersCount")));return Map.of("message","Weekly travel demand survey submitted");}
 @GetMapping("/analytics/survey-demand") public Map<String,Object> surveyDemand(){return Map.of("byRoute",db.queryForList("SELECT origin||' → '||destination AS label,COUNT(*) AS responses,COALESCE(SUM(passengers_count),0) AS passengers FROM survey_responses GROUP BY origin,destination ORDER BY responses DESC"),"byOrigin",db.queryForList("SELECT origin AS label,COUNT(*) AS responses FROM survey_responses GROUP BY origin ORDER BY responses DESC"),"byDestination",db.queryForList("SELECT destination AS label,COUNT(*) AS responses FROM survey_responses GROUP BY destination ORDER BY responses DESC"),"total",count("SELECT COUNT(*) FROM survey_responses"));}
 @PostMapping("/surveys") public Map<String,Object> survey(@RequestBody Map<String,Object> p){db.update("INSERT INTO surveys(passenger_id,origin,destination,route_code,travel_time,waiting_minutes,overcrowding,rating,comments) VALUES(?,?,?,?,?,?,?,?,?)",lng(p,"passengerId"),p.get("origin"),p.get("destination"),p.get("routeCode"),p.get("travelTime"),integer(p,"waitingMinutes"),integer(p,"overcrowding"),integer(p,"rating"),p.get("comments")); if(p.get("passengerId")!=null)db.update("UPDATE passengers SET points=points+10 WHERE id=?",lng(p,"passengerId"));return Map.of("message","Survey submitted","pointsAwarded",10);}
 @PostMapping("/requests") public Map<String,Object> request(@RequestBody Map<String,Object> p){db.update("INSERT INTO bus_requests(passenger_id,origin,destination,preferred_time,passengers_count) VALUES(?,?,?,?,?)",lng(p,"passengerId"),p.get("origin"),p.get("destination"),p.get("preferredTime"),integer(p,"passengersCount"));return Map.of("message","Bus demand request submitted");}
 @PostMapping("/incidents") public Map<String,Object> incident(@RequestBody Map<String,Object> p){String token="TV-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();db.update("INSERT INTO incidents(passenger_id,category,description,bus_number,route_code,location,urgency,evidence_name,evidence_sha256,token,anonymous) VALUES(?,?,?,?,?,?,?,?,?,?,TRUE)",lng(p,"passengerId"),p.get("category"),p.get("description"),p.get("busNumber"),p.get("routeCode"),p.get("location"),p.getOrDefault("urgency","NORMAL"),"", "NOT_ATTACHED",token);return Map.of("message","Incident submitted","token",token,"notice","For immediate danger call 112.");}
 @PostMapping(value="/incidents/upload",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> uploadIncident(@RequestParam Map<String,String> p,@RequestPart(value="evidence",required=false) MultipartFile evidence){try{return ResponseEntity.ok(saveUploaded(p,evidence,false));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error",Objects.toString(e.getMessage(),"Evidence upload failed")));}}
 @PostMapping(value="/incidents/rapid-sos",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ResponseEntity<?> rapidSOS(@RequestParam Map<String,String> p,@RequestPart("video") MultipartFile video){try{if(video==null||video.isEmpty())throw new IllegalArgumentException("A recorded video is required.");if(p.get("latitude")==null||p.get("longitude")==null)throw new IllegalArgumentException("Location is required.");if(p.get("busNumber")==null||p.get("busNumber").isBlank())throw new IllegalArgumentException("Bus code is required.");return ResponseEntity.ok(saveUploaded(p,video,true));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error",Objects.toString(e.getMessage(),"SOS upload failed")));}}
 private Map<String,Object> saveUploaded(Map<String,String> p,MultipartFile file,boolean rapid)throws Exception{
  String evidence="",hash="NOT_ATTACHED",storedPath=null;
  if(file!=null&&!file.isEmpty()){
   byte[] bytes=file.getBytes();hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
   Integer duplicates=db.queryForObject("SELECT COUNT(*) FROM incidents WHERE evidence_sha256=?",Integer.class,hash);
   if(duplicates!=null&&duplicates>0)throw new IllegalArgumentException("This exact evidence file was already submitted; duplicate blocked.");
   Path dir=Paths.get("uploads").toAbsolutePath().normalize();Files.createDirectories(dir);
   String original=Objects.toString(file.getOriginalFilename(),"evidence.bin");
   String ext=original.contains(".")?original.substring(original.lastIndexOf('.')):".bin";
   String safe=UUID.randomUUID()+ext.replaceAll("[^A-Za-z0-9.]","");
   Path target=dir.resolve(safe).normalize();if(!target.startsWith(dir))throw new IllegalArgumentException("Invalid evidence filename.");
   Files.write(target,bytes);storedPath=target.toString();evidence=safe;
  }
  Long passenger=p.get("passengerId")==null||p.get("passengerId").isBlank()?null:Long.valueOf(p.get("passengerId"));
  String token="TV-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();
  String checklist=(file!=null&&!file.isEmpty()?"1. Evidence bytes received and SHA-256 recorded; ":"1. No evidence attached; ")+"2. Server receipt timestamp recorded ("+Instant.now()+"); 3. Exact-file duplicate hash check completed. Original capture authenticity is NOT proven; human review required.";
  db.update("INSERT INTO incidents(passenger_id,category,description,bus_number,route_code,location,urgency,evidence_name,evidence_sha256,token,latitude,longitude,evidence_path,evidence_originality_status,ai_checklist,anonymous,is_rapid_sos) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
   passenger,p.getOrDefault("category",rapid?"Rapid SOS":"Other"),p.getOrDefault("description",""),p.get("busNumber"),p.get("routeCode"),p.getOrDefault("location",""),rapid?"URGENT":p.getOrDefault("urgency","NORMAL"),evidence,hash,token,asDouble(p.get("latitude")),asDouble(p.get("longitude")),storedPath,file==null||file.isEmpty()?"NOT_ATTACHED":"PENDING_HUMAN_REVIEW",checklist,true,rapid);
  Long incidentId=db.queryForObject("SELECT id FROM incidents WHERE token=?",Long.class,token);
  allocateNearest(incidentId,asDouble(p.get("latitude")),asDouble(p.get("longitude")));
  return Map.of("message",rapid?"Rapid SOS registered":"Complaint registered","token",token,"evidenceHash",hash,"verification","PENDING_HUMAN_REVIEW","notice","Prototype alert only; call 112 for real emergency dispatch.");
 }
 @GetMapping("/evidence/{id}") public ResponseEntity<Resource> evidence(@PathVariable long id)throws Exception{var rows=db.queryForList("SELECT evidence_path,evidence_name FROM incidents WHERE id=?",id);if(rows.isEmpty()||rows.get(0).get("evidence_path")==null)return ResponseEntity.notFound().build();Path file=Paths.get(rows.get(0).get("evidence_path").toString()).toAbsolutePath().normalize();Resource resource=new UrlResource(file.toUri());if(!resource.exists())return ResponseEntity.notFound().build();String lower=rows.get(0).get("evidence_name").toString().toLowerCase();MediaType type=lower.endsWith(".webm")?MediaType.parseMediaType("video/webm"):lower.endsWith(".mp4")?MediaType.parseMediaType("video/mp4"):lower.endsWith(".jpg")||lower.endsWith(".jpeg")?MediaType.IMAGE_JPEG:lower.endsWith(".png")?MediaType.IMAGE_PNG:MediaType.APPLICATION_OCTET_STREAM;return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"inline").contentType(type).body(resource);}
 private Double asDouble(String v){try{return v==null||v.isBlank()?null:Double.valueOf(v);}catch(Exception e){return null;}}
 @PostMapping("/incidents/escalate-overdue") public Map<String,Object> escalateOverdue(){int n=db.update("UPDATE incidents SET escalation_level=GREATEST(escalation_level,1),urgency='URGENT' WHERE is_rapid_sos=TRUE AND status NOT IN ('RESOLVED','CLOSED') AND assigned_at IS NOT NULL AND assigned_at < CURRENT_TIMESTAMP - INTERVAL '1 minute' AND escalation_level=0");return Map.of("escalated",n,"rule","Unaccepted Rapid SOS reports are flagged after one minute for authority review; this is an in-app escalation only.");}
 @GetMapping("/incidents") public List<Map<String,Object>> incidents(){return db.queryForList("SELECT i.id,i.category,i.description,i.bus_number,i.route_code,i.location,i.urgency,i.evidence_name,i.evidence_sha256,i.status,i.assigned_officer,i.created_at,i.token,i.latitude,i.longitude,i.evidence_path,i.evidence_originality_status,i.ai_checklist,i.anonymous,i.is_rapid_sos,i.points_awarded,CASE WHEN COALESCE(i.anonymous,TRUE) THEN 'Anonymous passenger' ELSE p.name END AS passenger_name FROM incidents i LEFT JOIN passengers p ON p.id=i.passenger_id ORDER BY CASE WHEN i.is_rapid_sos THEN 0 WHEN i.urgency='URGENT' THEN 1 ELSE 2 END,i.created_at DESC");}
 @GetMapping("/rewards/{id}") public Map<String,Object> rewards(@PathVariable long id){var r=db.queryForMap("SELECT points FROM passengers WHERE id=?",id);int pts=((Number)r.get("points")).intValue();return Map.of("points",pts,"demoRewardValueInr",pts/10,"conversionNote","Illustrative points value only; no cash payout integration.");}
 @GetMapping("/my-incidents/{id}") public List<Map<String,Object>> myIncidents(@PathVariable long id){return db.queryForList("SELECT * FROM incidents WHERE passenger_id=? ORDER BY created_at DESC",id);}
 @PatchMapping("/incidents/{id}") public Map<String,Object> updateIncident(@PathVariable long id,@RequestBody Map<String,String> p){String status=p.getOrDefault("status","UNDER_REVIEW");String note=p.getOrDefault("note","Status updated");db.update("UPDATE incidents SET status=?,assigned_officer=COALESCE(?,assigned_officer),resolved_at=CASE WHEN ?='RESOLVED' THEN CURRENT_TIMESTAMP ELSE resolved_at END WHERE id=?",status,p.get("assignedOfficer"),status,id);db.update("INSERT INTO complaint_updates(incident_id,status,note,updated_by) VALUES(?,?,?,?)",id,status,note,p.getOrDefault("updatedBy","Authority"));if(status.equals("RESOLVED")){Integer awarded=db.queryForObject("SELECT CASE WHEN points_awarded THEN 1 ELSE 0 END FROM incidents WHERE id=?",Integer.class,id);if(awarded!=null&&awarded==0){db.update("UPDATE incidents SET points_awarded=TRUE WHERE id=?",id);db.update("UPDATE passengers SET points=points+20 WHERE id=(SELECT passenger_id FROM incidents WHERE id=?)",id);db.update("INSERT INTO passenger_rewards(passenger_id,incident_id,points,reason) SELECT passenger_id,id,20,'Complaint verified and resolved' FROM incidents WHERE id=? AND passenger_id IS NOT NULL ON CONFLICT(passenger_id,incident_id) DO NOTHING",id);db.update("UPDATE officers SET points=points+25 WHERE name=(SELECT assigned_officer FROM incidents WHERE id=?)",id);db.update("INSERT INTO incentive_ledger(officer_id,incident_id,points,reason) SELECT id,?,25,'Verified incident resolution' FROM officers WHERE name=(SELECT assigned_officer FROM incidents WHERE id=?)",id,id);}}return Map.of("message","Complaint updated","status",status,"reward","Resolution points are awarded once in this prototype.");}
 @GetMapping("/analytics") public Map<String,Object> analytics(){return Map.of("passengers",count("SELECT COUNT(*) FROM passengers"),"surveys",count("SELECT COUNT(*) FROM surveys"),"requests",count("SELECT COUNT(*) FROM bus_requests"),"incidents",count("SELECT COUNT(*) FROM incidents"),"openIncidents",count("SELECT COUNT(*) FROM incidents WHERE status NOT IN ('RESOLVED','CLOSED')"),"routes",db.queryForList("SELECT route_code AS name,demand AS value FROM routes ORDER BY demand DESC"),"statuses",db.queryForList("SELECT status AS name,COUNT(*) AS value FROM incidents GROUP BY status"));}
 @GetMapping("/officers") public List<Map<String,Object>> officers(){return db.queryForList("SELECT * FROM officers ORDER BY name");}
 private long count(String q){Long v=db.queryForObject(q,Long.class);return v==null?0:v;}
 private Long lng(Map<String,Object> p,String k){Object v=p.get(k);return v==null||v.toString().isBlank()?null:Long.valueOf(v.toString());}
 private int integer(Map<String,Object> p,String k){Object v=p.get(k);return v==null||v.toString().isBlank()?0:Integer.parseInt(v.toString());}
 private String sha256(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes()));}catch(Exception e){return "HASH_ERROR";}}

 // Admin provisions officer accounts. Passwords are salted SHA-256 hashes for this academic prototype.
 @PostMapping("/admin/officers") public ResponseEntity<?> createOfficer(@RequestBody Map<String,Object> p){
  try{String email=Objects.toString(p.get("email"),"").trim().toLowerCase();String password=Objects.toString(p.get("password"),"");if(email.isBlank()||password.length()<8) return ResponseEntity.badRequest().body(Map.of("error","Email and password (minimum 8 characters) are required"));String salt=UUID.randomUUID().toString();String hash=salt+":"+sha256(salt+password);db.update("INSERT INTO officers(name,email,depot,role,phone,password_hash,station,available) VALUES(?,?,?,?,?,?,?,TRUE)",p.get("name"),email,p.getOrDefault("depot","Unassigned"),p.getOrDefault("role","Safety Officer"),p.get("phone"),hash,p.getOrDefault("station",p.getOrDefault("depot","Unassigned")));return ResponseEntity.ok(Map.of("message","Officer account created","email",email));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Could not create officer. Check duplicate email and required fields."));}}
 @PostMapping("/officers/login") public ResponseEntity<?> officerLogin(@RequestBody Map<String,String> p){var rows=db.queryForList("SELECT id,name,email,depot,role,points,available,password_hash FROM officers WHERE lower(email)=lower(?)",p.get("email"));if(rows.isEmpty())return ResponseEntity.status(401).body(Map.of("error","Invalid officer credentials"));String stored=Objects.toString(rows.get(0).get("password_hash"),"");String[] parts=stored.split(":",2);if(parts.length!=2||!sha256(parts[0]+Objects.toString(p.get("password"),"")).equals(parts[1]))return ResponseEntity.status(401).body(Map.of("error","Invalid officer credentials"));var o=new HashMap<String,Object>(rows.get(0));o.remove("password_hash");return ResponseEntity.ok(o);}
 @PostMapping("/officers/{id}/location") public Map<String,Object> officerLocation(@PathVariable long id,@RequestBody Map<String,Object> p){db.update("UPDATE officers SET latitude=?,longitude=?,available=? WHERE id=?",asDouble(Objects.toString(p.get("latitude"),null)),asDouble(Objects.toString(p.get("longitude"),null)),Boolean.parseBoolean(Objects.toString(p.getOrDefault("available",true))),id);return Map.of("message","Officer location updated");}
 @GetMapping("/officers/{id}/cases") public List<Map<String,Object>> officerCases(@PathVariable long id){return db.queryForList("SELECT i.*,a.status AS assignment_status,a.distance_km,d.name AS driver_name,d.phone AS driver_phone,d.email AS driver_email,b.latitude AS bus_latitude,b.longitude AS bus_longitude,b.last_location_at AS bus_last_location FROM incidents i JOIN incident_assignments a ON a.incident_id=i.id LEFT JOIN buses b ON b.bus_number=i.bus_number LEFT JOIN drivers d ON d.id=COALESCE(b.driver_id,i.driver_id) OR d.bus_number=i.bus_number WHERE a.officer_id=? ORDER BY i.created_at DESC",id);}
 @PostMapping("/officers/{id}/accept/{incidentId}") public ResponseEntity<?> acceptCase(@PathVariable long id,@PathVariable long incidentId){int n=db.update("UPDATE incident_assignments SET status='ACCEPTED',accepted_at=CURRENT_TIMESTAMP WHERE officer_id=? AND incident_id=? AND status='NOTIFIED'",id,incidentId);if(n==0)return ResponseEntity.badRequest().body(Map.of("error","Case is not awaiting this officer"));db.update("UPDATE incidents SET assigned_officer=(SELECT name FROM officers WHERE id=?),assigned_at=COALESCE(assigned_at,CURRENT_TIMESTAMP),status='UNDER_REVIEW' WHERE id=?",id,incidentId);return ResponseEntity.ok(Map.of("message","Case accepted. Contact the driver using the case details."));}
 @PostMapping("/officers/{id}/arrived/{incidentId}") public Map<String,Object> officerArrived(@PathVariable long id,@PathVariable long incidentId){db.update("UPDATE incident_assignments SET status='ARRIVED',arrived_at=CURRENT_TIMESTAMP WHERE officer_id=? AND incident_id=?",id,incidentId);db.update("UPDATE incidents SET arrived_at=CURRENT_TIMESTAMP,status='ACTION_TAKEN' WHERE id=?",incidentId);return Map.of("message","Arrival recorded");}
 @PostMapping("/admin/drivers") public ResponseEntity<?> createDriver(@RequestBody Map<String,Object> p){try{String salt=UUID.randomUUID().toString(),pw=Objects.toString(p.get("password"),"");if(pw.length()<8)return ResponseEntity.badRequest().body(Map.of("error","Password must be at least 8 characters"));db.update("INSERT INTO drivers(name,email,phone,password_hash,bus_number,depot_id) VALUES(?,?,?,?,?,?)",p.get("name"),p.get("email"),p.get("phone"),salt+":"+sha256(salt+pw),p.get("busNumber"),p.get("depotId")==null?null:Long.valueOf(p.get("depotId").toString()));return ResponseEntity.ok(Map.of("message","Driver account created"));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Could not create driver; check email and depot"));}}
 @PostMapping("/drivers/login") public ResponseEntity<?> driverLogin(@RequestBody Map<String,String> p){var rows=db.queryForList("SELECT id,name,email,phone,bus_number,depot_id,password_hash FROM drivers WHERE lower(email)=lower(?)",p.get("email"));if(rows.isEmpty())return ResponseEntity.status(401).body(Map.of("error","Invalid driver credentials"));String[] a=Objects.toString(rows.get(0).get("password_hash"),"").split(":",2);if(a.length!=2||!sha256(a[0]+Objects.toString(p.get("password"),"")).equals(a[1]))return ResponseEntity.status(401).body(Map.of("error","Invalid driver credentials"));var d=new HashMap<String,Object>(rows.get(0));d.remove("password_hash");return ResponseEntity.ok(d);}
 @PostMapping("/drivers/{id}/journey/start") public ResponseEntity<?> startJourney(@PathVariable long id,@RequestParam String busNumber,@RequestParam Double latitude,@RequestParam Double longitude,@RequestParam(required=false) String routeCode,@RequestParam(required=false) String routeName,@RequestParam(required=false) String scheduledStart,@RequestPart(value="photo",required=false) MultipartFile photo){try{String photoPath=null;if(photo!=null&&!photo.isEmpty()){Path dir=Paths.get("uploads").toAbsolutePath().normalize();Files.createDirectories(dir);photoPath=dir.resolve(UUID.randomUUID()+".jpg").toString();Files.write(Paths.get(photoPath),photo.getBytes());}db.update("UPDATE drivers SET bus_number=?,latitude=?,longitude=?,journey_active=TRUE,photo_path=?,last_location_at=CURRENT_TIMESTAMP WHERE id=?",busNumber,latitude,longitude,photoPath,id);db.update("INSERT INTO buses(bus_number,depot,status,latitude,longitude,last_location_at,driver_id) VALUES(?,(SELECT name FROM depots WHERE id=(SELECT depot_id FROM drivers WHERE id=?)),'ACTIVE',?,?,CURRENT_TIMESTAMP,?) ON CONFLICT(bus_number) DO UPDATE SET latitude=EXCLUDED.latitude,longitude=EXCLUDED.longitude,last_location_at=CURRENT_TIMESTAMP,driver_id=EXCLUDED.driver_id,status='ACTIVE'",busNumber,id,latitude,longitude,id);db.update("INSERT INTO journey_logs(driver_id,bus_number,latitude,longitude,photo_path,route_code,route_name,scheduled_start,punctuality_minutes) VALUES(?,?,?,?,?,?,?,?,CASE WHEN ?::timestamp IS NULL THEN NULL ELSE GREATEST(0,EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP-?::timestamp))/60)::int END)",id,busNumber,latitude,longitude,photoPath,routeCode,routeName,scheduledStart==null||scheduledStart.isBlank()?null:java.sql.Timestamp.valueOf(scheduledStart.replace("T"," ")+(scheduledStart.length()==16?":00":"")),scheduledStart==null||scheduledStart.isBlank()?null:scheduledStart,scheduledStart==null||scheduledStart.isBlank()?null:scheduledStart);return ResponseEntity.ok(Map.of("message","Journey started; GPS position registered"));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Could not start journey"));}}
 @PostMapping("/drivers/{id}/location") public Map<String,Object> driverLocation(@PathVariable long id,@RequestBody Map<String,Object> p){db.update("UPDATE drivers SET latitude=?,longitude=?,last_location_at=CURRENT_TIMESTAMP WHERE id=?",asDouble(Objects.toString(p.get("latitude"),null)),asDouble(Objects.toString(p.get("longitude"),null)),id);db.update("UPDATE buses SET latitude=?,longitude=?,last_location_at=CURRENT_TIMESTAMP WHERE driver_id=?",asDouble(Objects.toString(p.get("latitude"),null)),asDouble(Objects.toString(p.get("longitude"),null)),id);return Map.of("message","Bus GPS updated");}
 @PostMapping("/drivers/{id}/journey/stop") public Map<String,Object> stopJourney(@PathVariable long id){var rows=db.queryForList("SELECT id,punctuality_minutes FROM journey_logs WHERE driver_id=? AND ended_at IS NULL ORDER BY started_at DESC LIMIT 1",id);db.update("UPDATE drivers SET journey_active=FALSE WHERE id=?",id);int points=0;Long journeyId=null;if(!rows.isEmpty()){journeyId=((Number)rows.get(0).get("id")).longValue();Object lateObj=rows.get(0).get("punctuality_minutes");Integer late=lateObj==null?null:((Number)lateObj).intValue();boolean onTime=late!=null&&late<=5;points=onTime?30:10;db.update("UPDATE journey_logs SET ended_at=CURRENT_TIMESTAMP,completed_at=CURRENT_TIMESTAMP,points_awarded=TRUE WHERE id=?",journeyId);db.update("INSERT INTO driver_points(driver_id,journey_id,points,reason) VALUES(?,?,?,?)",id,journeyId,points,onTime?"Journey started within 5 minutes of schedule and completed":"Completed journey; departure punctuality not met/recorded");}return Map.of("message","Journey completed","pointsAwarded",points,"punctuality","30 points for departure within 5 minutes of schedule; 10 points for completed journey otherwise");}
 @GetMapping("/drivers") public List<Map<String,Object>> drivers(){return db.queryForList("SELECT id,name,email,phone,bus_number,depot_id,latitude,longitude,journey_active,last_location_at FROM drivers ORDER BY name");}
 @GetMapping("/depots") public List<Map<String,Object>> depots(){return db.queryForList("SELECT d.*,COUNT(DISTINCT b.id) AS bus_count,COUNT(DISTINCT i.id) FILTER (WHERE i.status NOT IN ('RESOLVED','CLOSED')) AS open_complaints FROM depots d LEFT JOIN buses b ON b.depot=d.name LEFT JOIN incidents i ON i.location ILIKE '%'||d.name||'%' GROUP BY d.id ORDER BY d.name");}
 @GetMapping("/officers/{id}/incentives") public Map<String,Object> incentives(@PathVariable long id){var r=db.queryForMap("SELECT COALESCE(SUM(points),0) AS points FROM incentive_ledger WHERE officer_id=?",id);return Map.of("points",r.get("points"),"withdrawalMinimumInr",2000,"estimatedValueInr",((Number)r.get("points")).intValue()/10,"withdrawals",db.queryForList("SELECT * FROM withdrawal_requests WHERE officer_id=? ORDER BY requested_at DESC",id));}
 @PostMapping("/officers/{id}/withdrawals") public ResponseEntity<?> withdraw(@PathVariable long id,@RequestBody Map<String,Object> p){double amount=Double.parseDouble(p.getOrDefault("amount","0").toString());if(amount<2000)return ResponseEntity.badRequest().body(Map.of("error","Minimum withdrawal is ₹2,000"));int points=(int)Math.ceil(amount*10);Integer earned=db.queryForObject("SELECT COALESCE(SUM(points),0) FROM incentive_ledger WHERE officer_id=?",Integer.class,id);if(earned==null||earned<points)return ResponseEntity.badRequest().body(Map.of("error","Insufficient earned points"));db.update("INSERT INTO withdrawal_requests(officer_id,amount_inr) VALUES(?,?)",id,amount);return ResponseEntity.ok(Map.of("message","Withdrawal request submitted for admin review"));}
 @PostMapping("/incidents/{id}/notify-driver") public Map<String,Object> notifyDriver(@PathVariable long id,@RequestBody Map<String,String> p){Long driverId=lng((Map)p,"driverId");if(driverId==null)return Map.of("error","Driver account is not linked to this bus");String msg=p.getOrDefault("message","Safety alert: please stop at the nearest safe and authorized location and await officer instructions.");db.update("INSERT INTO driver_notifications(incident_id,driver_id,message) VALUES(?,?,?)",id,driverId,msg);return Map.of("message","Driver notification queued","notice","This prototype records an in-app notification; it does not control the bus or guarantee delivery.");}
 @GetMapping("/drivers/{id}/notifications") public List<Map<String,Object>> driverNotifications(@PathVariable long id){return db.queryForList("SELECT * FROM driver_notifications WHERE driver_id=? ORDER BY created_at DESC",id);}
 private double distanceKm(double a,double b,double c,double d){double r=6371,dl=Math.toRadians(c-a),dn=Math.toRadians(d-b);double x=Math.sin(dl/2)*Math.sin(dl/2)+Math.cos(Math.toRadians(a))*Math.cos(Math.toRadians(c))*Math.sin(dn/2)*Math.sin(dn/2);return r*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
 private void allocateNearest(long incidentId,Double lat,Double lon){if(lat==null||lon==null)return;var candidates=db.queryForList("SELECT id,name,latitude,longitude FROM officers WHERE available=TRUE AND latitude IS NOT NULL AND longitude IS NOT NULL");candidates.sort((x,y)->Double.compare(distanceKm(lat,lon,((Number)x.get("latitude")).doubleValue(),((Number)x.get("longitude")).doubleValue()),distanceKm(lat,lon,((Number)y.get("latitude")).doubleValue(),((Number)y.get("longitude")).doubleValue())));int level=0;for(var o:candidates){double dist=distanceKm(lat,lon,((Number)o.get("latitude")).doubleValue(),((Number)o.get("longitude")).doubleValue());db.update("INSERT INTO incident_assignments(incident_id,officer_id,distance_km) VALUES(?,?,?) ON CONFLICT DO NOTHING",incidentId,o.get("id"),dist);level++;}if(!candidates.isEmpty()){var first=candidates.get(0);db.update("UPDATE incidents SET assigned_officer=?,assigned_at=CURRENT_TIMESTAMP,allocation_note=?,escalation_level=? WHERE id=?",first.get("name"),"Nearby officers notified in distance order; first eligible officer is primary",level,incidentId);}
  var bus=db.queryForList("SELECT d.id FROM incidents i JOIN buses b ON b.bus_number=i.bus_number JOIN drivers d ON d.id=b.driver_id WHERE i.id=? AND d.journey_active=TRUE",incidentId);if(!bus.isEmpty())db.update("INSERT INTO driver_notifications(incident_id,driver_id,message) VALUES(?,?,?)",incidentId,bus.get(0).get("id"),"URGENT SAFETY ALERT: Please stop only at the nearest safe and authorized location, keep passengers safe, and contact the assigned officer. Do not stop in a dangerous traffic lane.");}

 @PostMapping("/admin/depots") public ResponseEntity<?> createDepot(@RequestBody Map<String,Object> p){try{String pw=Objects.toString(p.get("password"),"");if(pw.length()<8)return ResponseEntity.badRequest().body(Map.of("error","Password must be at least 8 characters"));String salt=UUID.randomUUID().toString();db.update("INSERT INTO depots(name,latitude,longitude,manager_email,password_hash) VALUES(?,?,?,?,?)",p.get("name"),asDouble(Objects.toString(p.get("latitude"),null)),asDouble(Objects.toString(p.get("longitude"),null)),p.get("email"),salt+":"+sha256(salt+pw));return ResponseEntity.ok(Map.of("message","Depot account created"));}catch(Exception e){return ResponseEntity.badRequest().body(Map.of("error","Could not create depot account"));}}
 @PostMapping("/depots/login") public ResponseEntity<?> depotLogin(@RequestBody Map<String,String> p){var rows=db.queryForList("SELECT id,name,manager_email,latitude,longitude,password_hash FROM depots WHERE lower(manager_email)=lower(?)",p.get("email"));if(rows.isEmpty())return ResponseEntity.status(401).body(Map.of("error","Invalid depot credentials"));String[] a=Objects.toString(rows.get(0).get("password_hash"),"").split(":",2);if(a.length!=2||!sha256(a[0]+Objects.toString(p.get("password"),"")).equals(a[1]))return ResponseEntity.status(401).body(Map.of("error","Invalid depot credentials"));var d=new HashMap<String,Object>(rows.get(0));d.remove("password_hash");return ResponseEntity.ok(d);}
 @GetMapping("/depots/{id}/dashboard") public Map<String,Object> depotDashboard(@PathVariable long id){var d=db.queryForMap("SELECT * FROM depots WHERE id=?",id);String name=Objects.toString(d.get("name"),"");return Map.of("depot",d,"buses",db.queryForList("SELECT bus_number,latitude,longitude,status,last_location_at FROM buses WHERE depot=?",name),"drivers",db.queryForList("SELECT id,name,phone,bus_number,latitude,longitude,journey_active,last_location_at FROM drivers WHERE depot_id=?",id),"complaints",db.queryForList("SELECT id,category,location,bus_number,status,urgency,created_at,assigned_officer,assigned_at FROM incidents WHERE location ILIKE '%'||?||'%' ORDER BY created_at DESC",name),"surveyDemand",db.queryForList("SELECT origin||' → '||destination AS route,COUNT(*) AS responses,COALESCE(SUM(passengers_count),0) AS passengers FROM survey_responses GROUP BY origin,destination ORDER BY responses DESC"));}

 @GetMapping("/admin/accounts") public Map<String,Object> adminAccounts(){return Map.of("officers",db.queryForList("SELECT id,name,email,phone,depot,role,available,points FROM officers ORDER BY name"),"drivers",db.queryForList("SELECT id,name,email,phone,bus_number,depot_id,journey_active FROM drivers ORDER BY name"),"depots",db.queryForList("SELECT id,name,manager_email,latitude,longitude FROM depots ORDER BY name"));}
 @GetMapping("/incidents/{id}/driver-contact") public ResponseEntity<?> incidentDriverContact(@PathVariable long id){var rows=db.queryForList("SELECT d.id,d.name,d.phone,d.email,d.bus_number,d.latitude,d.longitude,d.journey_active,b.latitude AS bus_latitude,b.longitude AS bus_longitude FROM incidents i LEFT JOIN buses b ON b.bus_number=i.bus_number LEFT JOIN drivers d ON d.id=COALESCE(b.driver_id,i.driver_id) OR d.bus_number=i.bus_number WHERE i.id=?",id);if(rows.isEmpty()||rows.get(0).get("id")==null)return ResponseEntity.status(404).body(Map.of("error","No driver account is linked to this bus yet"));return ResponseEntity.ok(rows.get(0));}
 @PostMapping("/officers/{id}/cases/{incidentId}/resolve") public ResponseEntity<?> officerResolve(@PathVariable long id,@PathVariable long incidentId,@RequestBody Map<String,String> p){int n=db.update("UPDATE incident_assignments SET status='RESOLVED' WHERE officer_id=? AND incident_id=? AND status IN ('ACCEPTED','ARRIVED','NOTIFIED')",id,incidentId);if(n==0)return ResponseEntity.badRequest().body(Map.of("error","This case is not assigned to this officer"));db.update("UPDATE incidents SET status='RESOLVED',resolved_at=CURRENT_TIMESTAMP WHERE id=?",incidentId);db.update("INSERT INTO complaint_updates(incident_id,status,note,updated_by) VALUES(?,'RESOLVED',?,?)",incidentId,p.getOrDefault("note","Resolved by assigned officer"),"Officer "+id);Integer awarded=db.queryForObject("SELECT CASE WHEN EXISTS(SELECT 1 FROM incentive_ledger WHERE officer_id=? AND incident_id=?) THEN 1 ELSE 0 END",Integer.class,id,incidentId);if(awarded==null||awarded==0)db.update("INSERT INTO incentive_ledger(officer_id,incident_id,points,reason) VALUES(?,?,25,'Verified case resolution')",id,incidentId);db.update("UPDATE officers SET points=points+25 WHERE id=?",id);return ResponseEntity.ok(Map.of("message","Case resolved; 25 incentive points awarded")); }

 @GetMapping("/passengers/{id}/rewards") public Map<String,Object> passengerRewards(@PathVariable long id){var p=db.queryForMap("SELECT points FROM passengers WHERE id=?",id);return Map.of("points",p.get("points"),"catalog",db.queryForList("SELECT * FROM reward_catalog WHERE active=TRUE ORDER BY points_cost"),"history",db.queryForList("SELECT rr.*,rc.title FROM reward_redemptions rr JOIN reward_catalog rc ON rc.id=rr.reward_id WHERE rr.passenger_id=? ORDER BY rr.created_at DESC",id));}
 @PostMapping("/passengers/{id}/rewards/redeem") public ResponseEntity<?> redeemPassengerReward(@PathVariable long id,@RequestBody Map<String,Object> p){long rewardId=Long.parseLong(p.get("rewardId").toString());var r=db.queryForMap("SELECT id,title,points_cost FROM reward_catalog WHERE id=? AND active=TRUE",rewardId);int cost=((Number)r.get("points_cost")).intValue();Integer balance=db.queryForObject("SELECT points FROM passengers WHERE id=?",Integer.class,id);if(balance==null||balance<cost)return ResponseEntity.badRequest().body(Map.of("error","Not enough passenger points"));String code="TVR-"+UUID.randomUUID().toString().substring(0,8).toUpperCase();db.update("UPDATE passengers SET points=points-? WHERE id=?",cost,id);db.update("INSERT INTO reward_redemptions(passenger_id,reward_id,points_spent,redemption_code) VALUES(?,?,?,?)",id,rewardId,cost,code);return ResponseEntity.ok(Map.of("message","Demo reward redeemed","code",code,"reward",r.get("title"),"pointsSpent",cost));}
 @GetMapping("/drivers/{id}/points") public Map<String,Object> driverPoints(@PathVariable long id){return Map.of("points",db.queryForObject("SELECT COALESCE(SUM(points),0) FROM driver_points WHERE driver_id=?",Integer.class,id),"journeys",db.queryForList("SELECT id,bus_number,route_code,route_name,started_at,scheduled_start,completed_at,punctuality_minutes,points_awarded FROM journey_logs WHERE driver_id=? ORDER BY started_at DESC",id));}
 @GetMapping("/analytics/powerbi") public Map<String,Object> powerBiAnalytics(){return Map.of("kpis",Map.of("totalPassengers",count("SELECT COUNT(*) FROM passengers"),"resolvedComplaints",count("SELECT COUNT(*) FROM incidents WHERE status='RESOLVED'"),"openComplaints",count("SELECT COUNT(*) FROM incidents WHERE status NOT IN ('RESOLVED','CLOSED')"),"activeBuses",count("SELECT COUNT(*) FROM buses WHERE status='ACTIVE'"),"onTimeJourneys",count("SELECT COUNT(*) FROM journey_logs WHERE points_awarded=TRUE AND punctuality_minutes<=5"),"passengerPointsIssued",count("SELECT COALESCE(SUM(points),0) FROM passenger_rewards"),"driverPointsIssued",count("SELECT COALESCE(SUM(points),0) FROM driver_points")),"complaintsByStatus",db.queryForList("SELECT status AS label,COUNT(*) AS value FROM incidents GROUP BY status"),"complaintsByCategory",db.queryForList("SELECT category AS label,COUNT(*) AS value FROM incidents GROUP BY category ORDER BY value DESC"),"journeysByRoute",db.queryForList("SELECT COALESCE(route_name,route_code,'Unspecified') AS label,COUNT(*) AS value FROM journey_logs GROUP BY route_name,route_code ORDER BY value DESC"),"depotPerformance",db.queryForList("SELECT d.name AS label,COUNT(DISTINCT b.id) AS buses,COUNT(DISTINCT i.id) AS complaints FROM depots d LEFT JOIN buses b ON b.depot=d.name LEFT JOIN incidents i ON i.location ILIKE '%'||d.name||'%' GROUP BY d.name"));}
}
